INSERT INTO team_tactic_setups VALUES(1,'AVL','2025-26','FC26','optimal','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,'Emery 25/26: positional short build-up from the back (Martínez + Pau Torres BPD) — Short Passing. Defence is a compact 4-4-2 MID-block with opportunistic ball-winning, not an aggressive press or ultra-high line — Balanced, line ~52 (mid). CORRECTION 2026-07-02: previously High/68 from the 23/24 high-line narrative; 25/26-specific analyses (themastermindsite, totalfootballanalysis) and zero counter-goals-conceded contradict it — see tactic_observations scope=defence. Pairs with player_role_map kind=optimal. [2026-07-02 FORMATION PIN: in-game formation fixed to 4-2-3-1 Wide — left attacking slot is LM (WM type), so analysis-label LW prescriptions map to wm_* in-game equivalents and measured-nearest roles were refit vs wm kernels (see transfer_targets LM rows + player_role_map kind=role:LM).]','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — team-setting mapping grounded in 25/26 analyses + measured heatmaps, but not yet validated in-game. Validate by building the tactic in FC26, saving tactic_code, comparing in-game vs measured heatmaps.');
INSERT INTO team_tactic_setups VALUES(2,'AVL','2025-26','FC26','optimal:rogers10','4-2-3-1 Wide','Short Passing','Balanced',47,NULL,'PERSONNEL VARIANT of kind=optimal for the Rogers-at-No.10 XI (e.g. Baturina/Tavernier LM + Rogers CAM). Two data drivers (2026-07-03 인선-전술 분석, docs/20 규칙 B): (1) front-six normalized defensive share drops 31.0%→28.8% (lowest of all variants) — line lowered 52→47 to compensate; (2) attack flips right (unit lane L 18%→12%, Rogers CAM centroid x=57.5) — LEFT exposure is asymmetric, so pair with LB Attack compensation + RM wm_widemid/Support (rule A-3). Build-up stays Short Passing (deep drop-in creators support it). Counter is a contested/away experiment only.','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — same in-game-unvalidated caveat as kind=optimal; validate via tactic_code + in-game heatmap comparison.');
INSERT INTO team_tactic_setups VALUES(3,'AVL','2025-26','FC26','optimal:vs-strong','4-2-3-1 Wide','Short Passing','Deep',43,NULL,'vs 리버풀·시티급 강팀: 물러나 흡수. 실측 근거 리버풀전 PPDA 20.43, 시티전 14.44 (에메리는 강팀 상대 라인 내려 블록 유지). 문서 FC26_에메리_빌라_전술세팅.md §1 흡수. 빌드업은 base Short Passing 유지(문서는 Balanced 주장 — 미해결, tactic_code 검증 필요). [결과 보강 2026-07-02: 저점유(<=48%) 국면 14승1무2패(+1.00) — 첼시·토트넘 원정, 리버풀·시티·아스널전 포함. 흡수-역습이 팀의 최강 얼굴임을 결과가 확인. tactic_observations scope=possession.]','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — 게임 미검증, PPDA 실측 기반');
INSERT INTO team_tactic_setups VALUES(4,'AVL','2025-26','FC26','optimal:vs-weak','4-2-3-1 Wide','Short Passing','High',67,NULL,'vs 약팀·로우블록: 전방 압박 극대화. 실측 근거 울브스전 PPDA 4.99, 선덜랜드전 5.78. High까지가 상한(Aggressive 미사용 — 에메리는 선택적 압박, 게겐프레싱 아님). 문서 §1 흡수. [결과 보강 2026-07-02: 점유-성적 역상관 실측(r=-0.29, 45경기)이 이 변형의 필요를 결과 축에서 확인 — 고점유(>=55%) 국면 8승3무6패로 표본 내 패배 전부가 여기 몰림(CP H 0-3, 브렌트포드 H/A, 에버턴 H, 고어헤드). 로우블록 공략이 시즌의 약점 국면이었음. tactic_observations scope=possession.]','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — 게임 미검증, PPDA 실측 기반 | 점유-결과 실측으로 필요성 HIGH, 설정값 자체는 게임 검증 대상.');
INSERT INTO team_tactic_setups VALUES(5,'AVL','2025-26','FC26','optimal:lead','4-2-3-1 Wide','Short Passing','Deep',45,NULL,'리드 관리(후반 잠그기): 4-4-2 콤팩트 블록으로 템포 죽이기, 숏패싱 유지. 문서 §1 흡수. rest-defense(풀백 한 번에 한 명만 전진)가 역습 실점 0의 핵심.','FINAL (data-only) — 실측·분석 기반 확정. 게임 내 검증은 수동 플레이 환경이라 생략 (사용자 결정 2026-07-05). 이전 게이트: MEDIUM — 게임 미검증');
INSERT INTO team_tactic_setups VALUES(6,'AVL','2026-27','FC26','projected-deprecated','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,unistr('26/27 예상 XI (2026-07-22 이적 전망 기준): 마르티네스 gk_ballplaying/Build-Up — 캐시 fb_wingback/Balanced·콘사 cb_bpd/Aggressive·파우 토레스 cb_bpd/Build-Up·에스투피냔 fb_att_wb/Support — 고메스(LDM) dm_holding/Ball-Winning·카마라(RDM) dm_holding/Ball-Winning — 맥긴(RM) wm_widemid/Support·만잠비(CAM) cam_halfwinger/Balanced·가르나초(LM) wm_insidefwd/Attack — 왓킨스 st_advanced/Versatile. 팀 설정은 25/26 optimal 셸 유지(파운데이션-퍼스트, obs#6). 근거: 기존 7인=player_role_map optimal 처방, 영입 4인=transfer_targets 실측(에스투피냔 .946/가르나초 .911/만잠비 CAM .817/고메스 LDM .797). 피봇 좌우: 카마라 우중앙 앵커(duties#12)+고메스 좌측 우세 실측(.797 vs 우측 .638). 구조 판정: 더블 볼위닝 피봇→딥 창조 공백(보상: 파우 스텝업·만잠비 LDM 강하 dm_dlp .812·왓킨스 드롭), 좌측=공격 사이드(에스투피냔 오버랩+가르나초 인버티드), 캐비앗: 만잠비 halfwinger CAM-LM 충돌 0.72(가르나초 겹침)·시즌 초 실측 확인 항목. 변형 프리셋 후보: 만잠비 LDM+부엔디아 10번(잠긴 경기), 접전용 가르나초→Balanced형 스왑. 상세: reports/transfer-watch/2026-07-22.md [2026-07-29 우측 브리프 반영] RM 맥긴 wm_widemid/Support는 "디아비 이후 결손"을 균형자로 메운 상태이며 에메리의 실제 요구(뒷공간 침투 빠른 우측 윙어, Tanswell 1티어)와 다르다 — 영입 성사 시 이 슬롯이 최우선 교체 대상. 자금은 유출 선행 조건(SCR/합의금, 베일리→헐이 공간 창출 1순위).\u000a\u000a⛔ **[2026-07-31 폐기 — obs#82]** 이 프리셋은 결함 있는 측정 기준 위에 세워졌다: 슬롯 x 불일치(계단함수), 그리드 축 혼재, obs#29 타이브레이크 미적용, docs/20 §B의 근거 없는 라인 보상 규칙. 전수 재검토 후 단일 프리셋 ''projected:emery-2627''로 대체됐다. 행은 근거·이력 보존을 위해 남기되 kind에 -deprecated를 붙여 툴·조회에서 배제한다. 이 행의 인선·역할을 다시 인용하지 말 것.'),'PROJECTED — 이적 미확정 포함(가르나초 MEDIUM-HIGH·에스투피냔 HIGH, 나머지 CONFIRMED/보유). 26/27 실측 축적 후 measured/optimal로 대체 예정. 만잠비·고메스·에스투피냔·가르나초 처방은 타클럽/대표팀 실측 기반이라 빌라 컨텍스트 재검증 필요.');
INSERT INTO team_tactic_setups VALUES(7,'AVL','2026-27','FC26','projected:2up-4222-deprecated','4-2-2-2','Short Passing','Balanced',52,'',unistr('왓킨스+잭슨 투톱 예측(실측 아님). 26/27 projected 셸 유지 + 2번째 스트라이커 수용. 포메이션 근거: 빌라 포메이션 상수(4-2-3-1 41/45)의 투톱 예외가 4-2-2-2 ×1(번리 H)·4-4-2 ×3(본머스H·리즈A·첼시A) — 더블 피봇(고메스·카마라 dm_holding)을 보존하려면 4-2-2-2, 두 줄 4 뱅크/리드관리엔 4-4-2. 역할 스태거(핵심): 왓킨스 st_advanced/Attack(최전방 박스 피니셔+좌채널 배후, measured x41 좌편향·xg1.33·xa.03) / 잭슨 st_advanced/Support(하강 링크·양채널·전방압박, transfer_targets id123 실측 fit .752·x48). 2선=가르나초 wm_insidefwd/Attack(좌 내향)+만잠비 cam_halfwinger/Balanced(중앙 공급 — 로저스는 첼시 매각 £117m, 2026-07-25 정정). 폭=풀백 전담(에메리 한 번에 한 명, 캐시 Balanced rest-defense/에스투피냔 Support), 배후 리스크는 파우 스텝업+마르티네스 스위퍼로 상쇄. 수비 국면은 4-4-2 미드블록으로 회귀(기존 셸 정합). 툴 에메리구조 87(vs 4-2-3-1 예상 93)=구조 이탈 정량화. 대안 프리셋: 4-4-2(맥긴 RM·가르나초 LM wm_widemid/Support + 카마라·로저스 중앙 페어). [2026-07-29 우측 브리프 함의(obs#38)] 이 형태에는 **RM 슬롯이 없다**(2선=LM+CAM, 전방=ST 2). 따라서 브리프대로 침투형 우측 윙어를 영입하면 이 프리셋에는 자연스러운 자리가 없어 LM(가르나초와 경합) 또는 벤치가 된다 — 우측 영입과 투톱 전환은 상호 배타적 선택지로 취급할 것. 또한 4-2-2-2는 2선 2인이 모두 Attack/Balanced라 자기진영 질량이 0이며, 폭·뱅크를 풀백이 전담하는 구조상 obs#39의 뱅크 사다리를 적용할 RM 칸 자체가 없음.\u000a\u000a⛔ **[2026-07-31 폐기 — obs#82]** 이 프리셋은 결함 있는 측정 기준 위에 세워졌다: 슬롯 x 불일치(계단함수), 그리드 축 혼재, obs#29 타이브레이크 미적용, docs/20 §B의 근거 없는 라인 보상 규칙. 전수 재검토 후 단일 프리셋 ''projected:emery-2627''로 대체됐다. 행은 근거·이력 보존을 위해 남기되 kind에 -deprecated를 붙여 툴·조회에서 배제한다. 이 행의 인선·역할을 다시 인용하지 말 것.'),'QUALITATIVE — 예측(what-if) 세팅. 포메이션 상수 예외·에메리 커리어 4-4-2 DNA·잭슨 실측 st_advanced/Support(.752)·왓킨스 measured st_advanced에 근거. 리스크: 두 스트라이커 동시 드롭 시 박스 공동화, 무윙어 폭 부재. 시즌 실측으로 검증 예정.');
INSERT INTO team_tactic_setups VALUES(8,'CHE','2026-27','FC26','reference','5-4-1','Short Passing','High',64,'','알론소 레버쿠젠 블루프린트의 첼시 이식(참조 구현, 실측 아님). 부임 2026-05-17 발표·07-01 4년(첼시 공식/ESPN). 개념 골격: 3-4-2-1 스캐폴드 → 공격 3-2-5(5채널 오버로드)·수비 백5. ★FC26 슬롯 제약으로 인게임 포메이션은 5-4-1 채택: 3-4-2-1은 와이드=WM(윙백 역할 선택 불가)·중앙 2미들=CM이라 그리말도/프림퐁 윙백 역할 재현 불가 → 백5(FB 슬롯, fb_inverted/fb_att_wb 사용 가능)+4미드+1톱인 5-4-1이 정확 매핑(수비 국면 백5와도 일치, 공격 3-2-5 전개는 역할 커널 담당). 택티컬 비전=포제션(구 티키타카 — 볼 통제·중앙 지향 빌드업 정합; High Pressing 비전은 다이렉트 지향이라 부적합, 카운터프레스는 수비접근 High+라인 64로 구현). XI(스쿼드 2026-07-25 — 로저스£117m·팔레스트라£43m·퀜다£40m·에메가£22m IN / 쿠쿠레야·A.산투스·T.조지·가르나초(빌라 임대) OUT): 산체스 gk_ballplaying/Build-Up — 콜윌(LCB) cb_bpd/Aggressive(인카피에: 좌 전진 스텝) · 아다라비오요(CB) cb_bpd/Build-Up(타: 중앙 지휘·롱 대각) · 포파나(RCB) cb_wideback/Support(탑소바/코수누: 빌드업 시 와이드 이탈+볼캐리) — 아토(LWB) fb_inverted/Build-Up(그리말도: 딥→대각 내향 플레이메이커) · 팔레스트라(RWB) fb_att_wb/Attack(프림퐁: 터치라인 하이 윙어) — 엔소(LCM) cm_dlp/Build-Up(샤카 오케스트레이터) · 카이세도(RCM) cm_holding/Ball-Winning(팔라시오스 볼위너) — 로저스(LM) wm_wideplm/Attack(비르츠: 좌 하프스페이스 창조 — 빌라 실측 roaming 창조성 승계) · 팔머(RM) wm_insidefwd/Attack(호프만: 우 하프스페이스 득점 커넥터) — 주앙 페드루(ST) st_advanced/Support(보니페이스: 드롭 링크+카운터프레스 선봉). 비대칭 윙백=시스템 축(그리말도 yin/프림퐁 yang). 구조 리스크: 쿠쿠레야 매각으로 그리말도 롤 적임자 아토뿐(백3 좌측 겸직 불가), 중앙 상실 시 취약(레버쿠젠 동일). 로테이션: 제임스 RWB/RCB·에스테방/퀜다 RM·RWB·라비아/에수구 피봇·델랍/에메가 st_target·지튼스 LM·잭슨(빌라行 HIGH, XI 제외). 에메리 빌라(4-2-3-1 Balanced/52)와 대비: 5-4-1 High/64. 툴 프리셋 첼시 26/27 (알론소)와 계약. [2026-07-30 팀 축 도입] kind에 인코딩돼 있던 팀(reference:chelsea-alonso)을 team=CHE + kind=reference로 정규화. 당시 첼시 행이 player_role_map에 0개였으므로 조인 파괴 없음(A3 감사 Q1).','QUALITATIVE — 블루프린트 이식(첼시 실전 실측 아님). 레버쿠젠 전술은 themastermindsite·ac3lab·soccertutor·managingmadrid·bulinews 교차(2026-07-25 수집), 스쿼드는 Wikipedia 2026-27 Chelsea season + 첼시 공식 이적 페이지, FC26 슬롯 제약·비전 목록은 EA 커뮤니티 가이드(dexerto/beebom) 확인. 알론소가 첼시에서 레버쿠젠 골격을 그대로 쓸지는 미확인 — 시즌 개막 후 실측 검증 예정.');
INSERT INTO team_tactic_setups VALUES(9,'AVL','2026-27','FC26','projected:left-release-A-deprecated','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,unistr('좌측 해방(가르나초) 모드 설계안 — projected 셸에서 2슬롯 델타. ①CAM cam_playmaker/Roaming (projected의 만잠비 halfwinger 대체): 로저스 INTERPLAY 근거 — CAM halfwinger는 10번 포켓 질량 6.2→4.6 하락 + CAM-LM 충돌 0.45→0.72, 가르나초 wm_insidefwd/Attack 컷인 레인과 정면 충돌. playmaker/Roaming으로 포켓 보호. 캐비앗: 만잠비 CAM 실측최적은 halfwinger 0.817이라 긴장 — 바투리나(CAM 실측형, MEDIUM-HIGH) 영입이 완성 조건. ②LDM 고메스 dm_dlp/Roaming: 좌측 창작 소멸 시 후방 공급 필수(Package G 논리, 커버리지 21/25 복구). 캐비앗: 고메스 기능축=볼위너(obs#32) — 팔리냐(HIGH) 합류 시 팔리냐 RDM holding + 고메스 LDM dlp 분담이 정합. 나머지 셸 동일: 가르나초 LM insidefwd/Attack(.911, 수비복귀 완화 — 래시포드 선례 obs#36 자기진영 .145), LB 마첸 fb_att_wb/Support(디뉴 PSG行; 에스투피냔 영입 시 교체, 컷인 릴레이 겹침 .707 최저=상보), RM 맥긴 wm_widemid/Support 비협상(obs#27 두줄4 — 해방 윙어는 한 번에 한 명), 왓킨스 st_advanced/Versatile 우채널 우선. 용도: 기본 전술 + 강팀 Deep/43-45 모듈레이션(obs#8)에서 최대치 — 강팀전엔 가르나초 전방 F형 스왑(래시포드 강팀 4/5경기 전방 기용 선례). [2026-07-29 고메스 재검증 반영] LDM dm_dlp/Roaming을 고메스에게 처방하는 것은 기능 모순 확정(창조 전무 kp .3·xA .04, holding 재확정) — 이 프리셋의 후방 공급 요건은 진성 DLP형 영입(사라·베르그발·바투리나급) 전제이거나 고메스는 dm_boxcrasher/Balanced(.701, 숙련 보유) 절충으로 대체. [2026-07-29 우측 브리프 반영] Tanswell 1티어 브리프(뒷공간 침투 빠른 우측 윙어, 확정 관심 5명)로 RM 보강이 예정된 슬롯임이 확인 — 단 이 프리셋은 좌측이 해방 사이드라 신규 우측 윙어도 wm_widemid/Support로 강제(좌우 동시 해방 = obs#27 두 줄 4 붕괴). 즉 우측 영입의 Attack 가용은 B1 전용. 목표 커널은 wm_insidefwd이며 wm_winger 아님(디아비 실측 winger .577 < insidefwd .789). [2026-07-29 뱅크 사다리 반영(obs#39)] RM 맥긴 widemid/Support = 자기진영 0.60으로 전방 4인 중 유일한 뱅크 기여원(LM 가르나초 insidefwd/Attack은 0). 강팀 Deep/43-45 국면에서 뱅크를 더 조이려면 **widemid/Defend 또는 Balanced(자기진영 1.30, 2배)** 로 상향 가능 — 대가는 우측 공격 관여 축소. 이 프리셋에서 RM을 Attack 계열로 올리는 것은 뱅크를 0으로 만들어 A의 존재 이유(카운터 대비 블록)를 무너뜨리므로 금지.\u000a\u000a⛔ **[2026-07-31 폐기 — obs#82]** 이 프리셋은 결함 있는 측정 기준 위에 세워졌다: 슬롯 x 불일치(계단함수), 그리드 축 혼재, obs#29 타이브레이크 미적용, docs/20 §B의 근거 없는 라인 보상 규칙. 전수 재검토 후 단일 프리셋 ''projected:emery-2627''로 대체됐다. 행은 근거·이력 보존을 위해 남기되 kind에 -deprecated를 붙여 툴·조회에서 배제한다. 이 행의 인선·역할을 다시 인용하지 말 것.'),'DRAFT — 세션 설계 2026-07-29, 26/27 실측 전. 검증: 시즌 개막 후 가르나초·만잠비 히트맵 수집');
INSERT INTO team_tactic_setups VALUES(10,'AVL','2026-27','FC26','projected:interior-left-B1-deprecated','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,unistr('인테리어 좌측 모드 B1 — 부엔디아 딥 창작형. LM 부엔디아 wm_wideplm/Build-Up (role:LM 재적합 0.782; 좌8 실측 8선발 평점 7.09, 뉴캐슬전 "투웨이+박스 도착", 자기진영 점유 .277=래시포드의 2배 — 완전 뱅크 복귀형) + CAM 만잠비 cam_halfwinger/Balanced (실측최적 0.817 그대로 채택 가능 — Package G 커널 정합: LM wideplm/Build-Up이 측면 충돌 0.72→0.36 복구). 피벗은 projected의 더블 홀딩(고메스+카마라 dm_holding) 유지 가능 — 부엔디아가 딥 공급을 겸하므로 LDM dlp 불요, 고메스 기능축(볼위너, obs#32)과도 정합. LB 마첸 fb_att_wb/Support 임무 격상(좌측 폭 유일 공급원 — 디뉴 시즌 실측 .911 구조 재현). RM 재량 발생(좌측 뱅크 복귀 온전 — 25/26 산초 인버티드 실험이 전부 이 조건에서 나옴): 맥긴 Support 기본 + 알리송 로테이션 허용. 용도: 점유 주도/딥블록 상대 + 약팀 High/67 모듈레이션(obs#8). 에메리 모듈레이션 축1("10번의 정체: 로저스 vs 부엔디아 vs 틸레만스")의 부엔디아 항 상설화. [2026-07-29 사용자 확정 — RM 변경] 맥긴 wm_widemid/Support → wm_wideplm/Attack 기본 채택 (role:season 실측최적 .761 + 기능축 17.1m 중거리 12골=딥블록 킬러 + B1 좌측 뱅크 복귀 온전으로 해방 총량 1명 유지). 세트 조건: ①우측 폭 소멸 → 캐시 오버랩 모듈레이션(축4)과 병행, 마첸 전진 절제 ②FC26 wideplm 숙련 미보유(숙련=widemid) — 인게임 페널티 확인 필요, 확인 전까지 widemid/Support가 폴백. [2026-07-29 우측 브리프 반영 — 업그레이드 경로] 이 프리셋의 해방 우측 슬롯이 Tanswell 브리프의 착지점이다. 맥긴 wm_wideplm/Attack은 잠정치 — 침투 서명이 전방 0.49·자기진영 0.23으로 균형자형이라 브리프의 "뒷공간 반복 침투"를 충족하지 못한다. 영입 성사 시 하지무사 wm_insidefwd/Attack(.923, 전방 0.76·자기진영 0.14)로 교체가 정합 최상이며, 그 경우 맥긴은 RDM 딥롤(7.87) 또는 로테이션으로 이동. 로우·아데예미는 실측 PENDING이라 후순위 판단 보류. [2026-07-29 뱅크 비용 공개(obs#39) — 어제 RM 변경의 미고지 사항 교정] 맥긴 widemid/Support→wideplm/Attack 채택은 전방 4인 자기진영 질량을 0.60→**0.00**으로 만든다(wideplm는 Build-Up·Attack 모두 자기진영 0). 즉 이 프리셋은 더 이상 "두 줄 4 온전"이 아니라 **우측 뱅크를 의도적으로 포기한 구성**이다. 정당화: 용도가 딥블록 상대·약팀 High/67이라 상대가 우리 진영에서 공을 쥐는 시간이 적어 뱅크 손실의 실질 비용이 낮다. 제약 추가: **강팀 Deep/43-45 국면에서 이 프리셋 사용 금지** — 그 국면은 A(RM widemid/Support 0.60, 필요시 Defend/Balanced 1.30)를 쓸 것. 뱅크를 지키면서 인테리어 좌측을 원하면 B2.\u000a\u000a⛔ **[2026-07-31 폐기 — obs#82]** 이 프리셋은 결함 있는 측정 기준 위에 세워졌다: 슬롯 x 불일치(계단함수), 그리드 축 혼재, obs#29 타이브레이크 미적용, docs/20 §B의 근거 없는 라인 보상 규칙. 전수 재검토 후 단일 프리셋 ''projected:emery-2627''로 대체됐다. 행은 근거·이력 보존을 위해 남기되 kind에 -deprecated를 붙여 툴·조회에서 배제한다. 이 행의 인선·역할을 다시 인용하지 말 것.'),'DRAFT — 세션 설계 2026-07-29, 26/27 실측 전. 부엔디아 25/26 실측은 완비, 조합 검증만 남음');
INSERT INTO team_tactic_setups VALUES(11,'AVL','2026-27','FC26','projected:interior-left-B2-deprecated','4-2-3-1 Wide','Short Passing','Balanced',52,NULL,unistr('인테리어 좌측 모드 B2 — 인사이드포워드형(로저스 직무 승계 트랙). LM 만잠비 wm_insidefwd/Balanced (0.700, 중앙 회귀 성향 — 로테이션 등급) + CAM cam_playmaker/Roaming (포켓 질량 6.2, 창작+도착 분담 구조 — B1의 더블 창작과 구별). 장기 1옵션: 헤밍스 — 에메리가 left 10 프로젝션(Tanswell/The Athletic 2026-07), 박스투박스→인테리어 전환은 램지 개발 경로 재현, 단 1군 실측 표본 부재로 PENDING(45분+ 출전 축적 시 히트맵 수집). 가르나초 Balanced 하향 기용은 실측(Attack 0.911) 미스핏이라 비권장 — B2의 LM은 만잠비/헤밍스 전용, 가르나초 선발이면 left-release-A 사용. 나머지 슬롯 B1과 동일(더블 홀딩, LB 마첸 폭 전담, RM 재량). 용도: B1과 같은 점유 국면이나 부엔디아 부재/세대교체 이후의 대안. [2026-07-29 우측 브리프·뱅크 사다리 반영(obs#38·39)] 이 프리셋의 정체성 확정 = **양쪽 절제형(뱅크 온전)**. RM 맥긴 widemid/Support(자기진영 0.60)를 유지하므로 3종 중 유일하게 전방 4인의 자기진영 질량이 남는다(B1은 wideplm/Attack 채택으로 0.00). 좌측 LM insidefwd/Balanced는 커널 자기진영이 0이라 뱅크에 기여하지 않음 — 뱅크는 RM 한 칸이 단독 결정(obs#39). 용도 확장: 원래의 점유 국면 대안 + **리드관리(Deep/45)·뱅크가 필요한 국면의 인테리어 옵션**. 신규 우측 윙어(브리프) 투입 시: insidefwd 계열은 Attack·Balanced 모두 자기진영 0이라 이 프리셋의 성격을 파괴하므로, 뱅크를 지키려면 widemid/Support(0.60) 또는 winger/Balanced(0.30) 절충이 필요하고, 침투형 Attack 사용은 B1에서 하라.\u000a\u000a⛔ **[2026-07-31 폐기 — obs#82]** 이 프리셋은 결함 있는 측정 기준 위에 세워졌다: 슬롯 x 불일치(계단함수), 그리드 축 혼재, obs#29 타이브레이크 미적용, docs/20 §B의 근거 없는 라인 보상 규칙. 전수 재검토 후 단일 프리셋 ''projected:emery-2627''로 대체됐다. 행은 근거·이력 보존을 위해 남기되 kind에 -deprecated를 붙여 툴·조회에서 배제한다. 이 행의 인선·역할을 다시 인용하지 말 것.'),'DRAFT — 세션 설계 2026-07-29. LM 후보(만잠비 LM 0.700 로테이션급, 헤밍스 실측 無)라 3안 중 최저 우선순위');
INSERT INTO team_tactic_setups VALUES(12,'AVL','2026-27','FC26','projected:right-release-C-deprecated','4-2-3-1 Wide','Short Passing','Balanced',48,NULL,unistr('우측 침투 모드 (C) — obs#38 브리프("수비 뒷공간으로 반복 침투하는 빠른 우측 윙어")의 전용 착지 프리셋. 기존 A/B1/B2에 한 칸 교체로 수용 불가한 이유: ①용도 축이 다르다 — 침투형 우측 윙어의 가치는 배후 공간이 존재할 때 발생하므로 상대는 하이라인·압박팀(첼시 알론소 High/64, 뉴캐슬, 스퍼스)·트랜지션 경기이며, B1의 용도(딥블록 상대·약팀 High/67 = 배후 공간 없음)와 정반대다 ②뱅크 사이드가 반대로 뒤집힌다(obs#39 보정) ③ST 채널·풀백 좌우가 함께 바뀐다. 구조 = **A의 정확한 거울상**: A가 좌측 해방(LM Attack + LB 오버랩) + 우측 뱅크(RM Support + RB 절제)라면, C는 우측 해방(RM insidefwd/Attack + RB 오버랩) + 좌측 뱅크(LM widemid/Support 0.60 + LB 절제). 전방 4인 뱅크 0.60으로 A와 동일 — 딥블록 전용인 B1(뱅크 0.00)과 달리 상대가 공을 쥐는 경기에 사용 가능. 슬롯별 근거: RM insidefwd/Attack = 침투 서명 최상 후보 하지무사(.923, 전방 0.76·자기진영 0.14, 우채널 전방 질량 2.8) / CAM cam_playmaker/Roaming = RM 겹침 0.16 최소 + 침투 런 공급(halfwinger는 겹침 0.57로 배제, shadow/Attack 0.14는 자신이 침투해 공급 부재) / ST 왓킨스 st_advanced/**Attack** = RM 겹침 0.31(Versatile)→0.17로 축소 + 실측 중심 x=41.1 좌편향이라 우채널을 비워줌(잭슨 Support는 겹침 0.44로 최악 — 잭슨 선발 시 이 프리셋 부적합) / LM wm_widemid/Support = 좌측 뱅크 전담(자기진영 0.60) / 풀백 좌우 스왑: RB 캐시 fb_att_wb/Support(침투 뒤 빈 우측 폭 재점유 릴레이 — 래시포드×디뉴 겹침 .707 궁합의 우측 거울상), LB 마첸 fb_wingback/Balanced(절제, 뱅크 보존, "풀백 한 명씩만 전진" 준수). 팀설정은 파운데이션 상수 유지 — 상대가 극단 하이라인이면 라인 52→45 하향으로 배후를 더 넓히는 모듈레이션(obs#8 메커니즘) 권고. [2026-07-29 수비가담 검증 → 라인 52→48 하향] docs/20 §B 규칙(정규화 수비가담 = 실측 그리드 자기진영 하위 2행 질량비, 전방 6인 평균, 기본 XI 기준선 31.0%, -1.3pt 이상 이탈 시 라인 보상)을 적용한 결과 이 프리셋은 **27.8% (-3.2pt)** 로 문서에 기록된 최저 사례(바투리나L+로저스10 28.8%, -2.2pt)보다도 낮다. 원인: 침투형 우측 윙어(하지무사 14.0%)와 왓킨스(14.7%)가 전방 두 칸을 차지해 실측 수비가담이 구조적으로 낮고, 좌측 뱅크(맥긴 23.0%)와 피벗(고메스 38.3·카마라 49.3)으로도 상쇄가 부족. 따라서 라인 보상은 상대 유형과 무관하게 **필수**이며(당초 "극단 하이라인 상대에만 권고"는 과소 처방), Balanced 유지 + 라인 **48** 을 기본값으로 확정. 추가 보상 옵션: LM을 widemid/**Defend**로(커널 자기진영 0.60→1.30, §B의 "역할 보상 = LM 포커스 Defend 계열" 정합) — 대가는 좌측 공격 관여 축소. RM 대안 은디아예(14.8%)도 28.0%로 동일 문제. **중요 구분**: 여기서 쓰는 자기진영 수치는 실측 그리드(수비 국면 포함) 기반의 정규화 수비가담%이며, 프리셋 설계에 쓴 커널 자기진영 질량(0.60/1.30/0.00 = 역할이 지시하는 위치 깊이)과는 별개 축이다 — obs#39 혼용 금지 조항 참조.\u000a\u000a⛔ **[2026-07-31 폐기 — obs#82]** 이 프리셋은 결함 있는 측정 기준 위에 세워졌다: 슬롯 x 불일치(계단함수), 그리드 축 혼재, obs#29 타이브레이크 미적용, docs/20 §B의 근거 없는 라인 보상 규칙. 전수 재검토 후 단일 프리셋 ''projected:emery-2627''로 대체됐다. 행은 근거·이력 보존을 위해 남기되 kind에 -deprecated를 붙여 툴·조회에서 배제한다. 이 행의 인선·역할을 다시 인용하지 말 것.'),'DRAFT — 세션 설계 2026-07-29, 영입 전제(하지무사 MEDIUM-HIGH). **미해결 과제 2건**: ①LM widemid/Support 인선 공백 — 이 프로필의 보유자는 맥긴뿐인데 그의 실측·처방은 우측 전용이라 좌측 배치는 미러 가정(미검증, 아데예미 LM 0.24 사례처럼 확정 판정과 구분). 대안 만잠비는 widemid 실측 부재. 좌측 뱅크형 영입 또는 맥긴 좌측 실측 확보가 완성 조건 ②배후 공급이 CAM 단일 실패점 — 더블 홀딩(고메스·카마라 모두 볼위너, obs#32·어제 재검증)이라 딥 공급이 없어 CAM 봉쇄 시 침투 무력화. 진성 DLP형(사라·베르그발 MEDIUM-HIGH) 영입 또는 팔리냐(HIGH) 합류로 피벗 재편이 필요. ③왓킨스 Attack은 3축 처방(Versatile, obs#12)의 국면 한정 예외 — 2up-4222 선례 있음. ④수비가담 -3.2pt로 라인 48 기본값 확정(2026-07-29) — 실제 블록 견고성은 툴로 검증 불가(obs#27 한계)이므로 게임 내 실사용에서 재확인 필요.');
INSERT INTO team_tactic_setups VALUES(13,'CHE','2025-26','FC26','measured','4-2-3-1',NULL,NULL,NULL,NULL,'첼시 25/26 실측 기준선. ⚠️ 이 시즌 감독은 알론소가 아니다 — 마레스카(~2026-01-01) → 맥팔레인 대행 → 로즈니어(01-08~04-22) → 맥팔레인(04-22~). PL 9경기 표본 조사 결과 4-2-3-1이 7경기로 압도적 기본형이며 백3/백5는 로즈니어 말기 브라이턴 원정·맥팔레인 최종전의 예외. 결과 PL 10위, 26/27 유럽대회 없음. 이 행의 용도는 "알론소 전술"이 아니라 **선수 개인의 위치 성향 기준선**이다.','MEASURED(선수 히트맵 SofaScore PL 25/26) / ⚠️ 팀 전술은 알론소와 무관 — 알론소 첼시 공식전 0경기(첫 경기 2026-08-24 풀럼). 알론소 처방은 team=CHE, season=2026-27 행 참조.');
INSERT INTO team_tactic_setups VALUES(14,'LIV','2025-26','FC26','measured','4-2-3-1',NULL,NULL,NULL,NULL,'리버풀 25/26 실측 기준선. 감독은 **아르네 슬롯 단일 체제**(38R 전부) — 2026-05-30 경질, 후임 이라올라는 2026-06-04 부임(구단 공식, 2년)이므로 이 행에 이라올라 전술은 없다. 4-2-3-1이 기본형이고 변형은 4-2-2-2(UCL vs PSG — LM/RM 소멸로 11슬롯 매핑 불가)와 무소유 4-2-4 압박 셰이프. 성적 PL 5위 60점, UCL 8강. 이라올라의 기본형도 4-2-3-1이라 26/27도 프로젝트 슬롯과 1:1 대응이 유지된다.','MEASURED(선수 히트맵 SofaScore PL 25/26) / ⚠️ 팀 전술은 이라올라와 무관. 26/27 3개 슬롯(RCB·RM·LB)은 주인이 바뀌었다: 코나테→레알, 살라→FA, 로버트슨→토트넘.');
INSERT INTO team_tactic_setups VALUES(15,'CHE','2026-27','FC26','projected','3-4-2-1','Short Passing','Balanced',58,NULL,'알론소 첼시 26/27 처방 — **첼시 25/26 개인 실측(team=CHE, kind=measured)에 알론소 원칙(obs 40~62)을 얹은 파생**이며 알론소 실측은 0경기다. 백3 구성이 실측으로 강하게 지지된다: 하토 LCB 0.930(CCB 0.495·RCB 0.377) / 찰로바 **CCB 0.873**(LCB 0.665·RCB 0.744) / 포파나 RCB 0.953(CCB 0.669·LCB 0.424) — 세 명이 각자 자기 자리에서 최고치이고 다른 자리에서 급락한다. 이것이 **CCB 슬롯 신설의 실측 근거**다(중앙 CB를 좌우로 흡수하면 찰로바 0.873이 0.744로 깎인다). 슬롯 매핑: 3-4-2-1의 두 하프스페이스 10번을 **LM·RM에 배치하고 CAM 슬롯은 비운다**(11칸 유지). 라인 58은 파운데이션 52보다 높게 두되 obs#37의 "하이라인" 근거 미달 정정(1~2티어에 라인 높이 수치 없음, PL 공식은 오히려 더 깊은 구조로 서술)을 반영해 64에서 하향.','PROJECTED — ⚠️ 알론소 첼시 공식전 0경기(첫 경기 2026-08-24 풀럼). 개인 실측은 25/26 마레스카·로즈니어 체제 표본이므로 팀 전술 근거가 아니다. 미해결 3건: ① **좌 윙백(LB) 실측 공백** — 쿠쿠렐라 레알 이적, 팔레스트라·케다는 첼시 실측 0. obs#61이 지목한 "좌측이 구조 최약 슬롯"이 처방에서도 그대로 공백으로 남는다. ② **RDM 인선 문제** — 엔소는 RDM 적합 0.361로 부적합(LDM 0.698)이라 카이세도(LDM 0.941)와 같은 쪽을 원한다. 우측 피벗에 맞는 유일한 실측 인원이 리스 제임스(0.772)인데 표본 3경기. ③ **알론소 지시와 실측의 충돌** — 그는 팔머·로저스를 "포켓(스트라이커 근처·10번 근처)"으로 규정했으나 실측은 팔머 RM 0.845(CAM 0.676)·로저스 LM 0.733(CAM 0.664)으로 **중앙이 아니라 좌우 와이드**를 지시한다. 즉 이 처방의 2×10은 알론소의 언어가 아니라 실측의 언어다. 캐비앗: 찰로바·제임스 표본 3경기, 로저스 그리드는 빌라 25/26(에메리 체제) 것.');
INSERT INTO team_tactic_setups VALUES(16,'AVL','2026-27','FC26','projected:emery-2627','4-2-3-1 Wide','Short Passing','Balanced',52,'',unistr('⭐ **에메리 실축 구현 프리셋 (2026-07-31 전수 재설계)** — 기존 26/27 프리셋 5종을 폐기하고 obs#82의 재정립된 측정 기준 위에 단일 프리셋으로 세웠다. 목적은 ''최적 적합''도 ''게임 최강''도 아니고 **에메리 전술의 게임 내 구현**이다.\u000a**XI(평균 적합 0.849)**: 마르티네스 gk_goalkeeper/Defend .961 — 에스투피냔(LB) fb_att_wb/Support **.946** · 파우 토레스(LCB) cb_bpd/Build-Up .882 · 콘사(RCB) cb_bpd/Aggressive .938 · **보가르드(RB) fb_att_wb/Support .890** — 만잠비(LDM) dm_dlp/Roaming .812 · 카마라(RDM) dm_holding/Ball-Winning .618 — 가르나초(LM) wm_insidefwd/Attack .911 · 맥긴(CAM) cam_playmaker/Roaming .801 · **캐시(RM) wm_widemid/Support .835** · 잭슨(ST) st_advanced/Support .752.\u000a**설계 근거 5축**: ① 셸 고정(obs#25 재검증: formation_v 4-2-3-1 41/45=91.1%, 롱볼 9.39% vs 상대 11.08%) ② 수비 접근 Balanced 외 선택지 없음(obs#27 — Deep은 두 줄 간격을 벌리고 High/Aggressive는 과압박) ③ 두 줄 4는 RM 한 칸이 결정(obs#39) — 좌측 해방(가르나초 뱅크 0.00)이므로 우측 widemid 필수. 알리송 .807이 맥긴 .728보다 이 역할에 맞고, 전방 4인 뱅크 **0.60은 전량 알리송 기여**. 측정최적 insidefwd(.847)를 버리고 .040을 구조에 지불한 칸이다. ④ 풀백 한 명씩 전진(obs#4) — 커널로 검증: LB 전방 1.30/자기진영 0.90 vs RB 전방 0.30/자기진영 1.60 = **비대칭 성립**. 가르나초가 안으로 들어가 비는 좌측 폭을 에스투피냔이 메우고 캐시는 Balanced로 백4 유지(obs#27 ''풀백 과공격 배제''). ⑤ 피벗 = 볼위너 + 창조형(obs#32·#11) — 틸레만스 유출로 사라진 창조 축을 만잠비 dm_dlp가 승계. 카마라 .618이 최저 슬롯인 것은 의도된 것으로, 움직임 최적 dm_dlp/Roaming(.765)을 버리고 기능축(듀얼 8.4·인터셉트 3.0 스쿼드 1위, obs#31)을 택해 **.147을 구조에 지불**했다.\u000a**라인 52 유지** — 전방 6인 수비가담 23.4%로 기준선(시즌축 30.3%) 대비 −6.9pt이지만, docs/20 §B의 라인 하향 규칙은 obs#27과 모순되어 **폐기**됐다(obs#82 ⑤). 부족분은 **역할 보상**으로 처리한다: 알리송 wm_widemid/Support(뱅크 0.60) → **Defend 또는 Balanced(뱅크 1.30, 적합 .628)**. 라인 변형은 obs#3의 실측 근거값만 사용(강팀 43 · 약팀 67 · 리드 45).\u000a**벤치**: 마첸 LB fb_wingback/Balanced .862(수비가담 54.8 — 리드 관리) · 시세 RCB .890(콘사 이탈 대비) · 보가르드 RDM dm_dlp/Roaming .790 · 만잠비 CAM cam_halfwinger/Balanced .817(LDM은 고메스 .797) · 부엔디아 LM wm_wideplm/Attack .755 · 왓킨스 ST st_false9/Attack .722 · 맥긴 RM wm_widemid/Support .728 · 린델뢰프 LCB .641.\u000a\u000a**[2026-07-31 갱신 — obs#89 C안 반영]** RB 캐시 → **보가르드 fb_wingback/Support .808**, RM 알리송 → **캐시 wm_widemid/Support .835**.\u000a근거: 두 줄 4의 뱅크 칸(RM)이 하는 일이 정확히 **오프더볼 복귀**인데(obs#88), 알리송의 RM 숙련 역할은 **wm_winger**이지 wm_widemid가 아니다 — 즉 기존 처방은 **뱅크에 미숙련 배치**였다. 캐시는 sofifa 숙련에 wm_widemid를 보유하고 적합도 0.835로 알리송(.807 미숙련)·맥긴(.728)보다 높다. 캐시가 RM으로 올라간 자리는 보가르드가 받는다.\u000a**대가**: XI 평균 적합 **0.847 → 0.842**(−0.005). 전방 4인 뱅크 **0.60 유지**(전량 캐시 기여), C1(두 줄 4)·C2(풀백 한 명씩 전진 — LB 에스투피냔 전방 1.30 vs RB 보가르드 0.30)·C3(피벗 분화) 전부 성립.\u000a**보가르드 RB 포커스**: 측정최적은 fb_att_wb/Support .890이나 그는 att_wb **미숙련**, fb_wingback 숙련이다. 뱅크·rest-defense 성격의 칸이므로 wingback/Support를 채택하고 **Δ0.082를 구조에 지불**했다 — obs#29의 Δ≤0.03 기계 규칙이 아니라 명시적 지불이다.\u000a**obs#89 기록 정정 2건**(툴 커널 재계산, 2026-07-31): ① 보가르드 fb_wingback/Support는 **0.808**이다(obs#89의 0.764는 재현되지 않음). ② obs#89의 "C = 미숙련 0칸"은 **3안이 서로 다른 칸(RB·RM·CAM·LDM)에 한정된 비교**다 — XI 전체로 보면 GK 마르티네스(숙련 gk_ballplaying만)·LCB 파우 토레스·RCB 콘사(둘 다 숙련 cb_defender)·LB 에스투피냔(숙련 fb_wingback만)의 **4칸이 여전히 미숙련**이며, 이들은 3안 공통이라 선택에 영향을 주지 않는다.\u000a**신규 캐비앗 2건**: ⑴ **캐시 RM 그리드는 RB 실측**이다(RM 실측 0경기) — 슬롯 x가 87 vs 85로 거의 같아 계산은 성립하나, 실제로 RM에 서면 위치가 더 높아질 것이므로 0.835는 상한이 아니라 **미검증 추정치**다. ⑵ 그 결과 RB×RM 충돌 CI가 0.11(캐시RB×알리송RM) → **0.51**(보가르드RB×캐시RM)로 올랐다. 경고선(1.0) 미만이지만, 두 그리드가 **모두 RB 실측**이라는 축 인공물이 섞여 있다.\u000a⚠️ **보가르드 RB 그리드는 긴급 출전 1경기 표본**이 유일한 약점이다(obs#84 ⑦).\u000a\u000a**[2026-07-31 재정정 — obs#91 EA 피치노트 반영, 사용자 확정]** 보가르드 RB 포커스를 **fb_att_wb/Support .890(측정최적)** 으로 되돌린다.\u000a경위: 같은 날 obs#89 반영에서 미숙련 회피를 위해 wingback/Support .808을 채택하고 Δ0.082를 지불했으나, 직후 확보한 **EA 공식 피치노트**가 *"regular Roles와 Roles+를 Roles++에 가깝게 끌어올렸다"* · *"Out of Position 페널티를 대폭 줄였다"* 고 **명시**한다(obs#91 ②). 숙련 프리미엄이 축소된 시스템에서 Δ0.082는 과한 대가이며, 이 Δ는 obs#91 ①이 정한 노이즈 구간(0.02~0.05)보다 크므로 **적합 우선이 방어 가능**하다. XI 평균 적합 0.842 → **0.849**.\u000a**RM 캐시는 유지한다** — 그 칸의 Δ는 0.028로 노이즈 구간 안이라 같은 규칙이 반대로 적용된다(작은 Δ는 숙련 같은 이산 근거로 가른다, obs#29·#91 ①).\u000a⚠️ **알려진 구조 이탈 1건 — C2 붕괴**: LB 에스투피냔도 `fb_att_wb/Support`(전방 1.30)라 두 풀백의 전방 질량이 **정확히 동률**이 되어 **C2(풀백 한 명씩만 전진, obs#4·#27)가 성립하지 않는다**. 이 프리셋은 이제 **양쪽 풀백이 모두 전진형**이며, 이는 obs#27의 ''풀백 과공격 배제''와 충돌한다. 사용자 확정 사항으로 그대로 두되, 비대칭이 필요한 국면(강팀 Deep/43·리드 관리 45)에서는 **RB를 `fb_wingback/Support` .808(전방 0.30)로 내려 복원**할 것 — 이것이 유일한 복원 옵션이다(에메르송은 수비형 옵션이 .637/.680에 전 역할 미숙련이라 대안이 못 된다).\u000a**나머지 obs#89 C안 항목은 유지**: RM 캐시 wm_widemid/Support .835(숙련✓, 뱅크 0.60) · CAM 맥긴 cam_playmaker/Roaming .801.'),'PROJECTED — 26/27 공식전 0경기. 스쿼드 기준: 확정 영입(가르나초·만잠비·고메스·시세) + 영입 HIGH(잭슨) + 사용자 지정 포함(에스투피냔 MEDIUM-HIGH) + 보유. 제외: 산초(사용자 지시), 확정 유출 4명, 베일리(HIGH). 팔리냐는 사용자 지시로 스쿼드에서 제외. ⚠️ 한계 4건: ① **축 미통일** — 보유는 season, 영입 4명(에스투피냔·가르나초·만잠비·잭슨)은 빌라 경기 0이라 최근 6경기 축. ② **에스투피냔 MEDIUM-HIGH**(밀란 블록 미해제) — 무산 시 마첸 .862 대체, 그 경우 좌측 전진 성격이 약해진다. ③ **이탈 리스크 3칸**(마르티네스 유벤투스 HIGH · 왓킨스 맨유 MH · 콘사 아스날 MH) — 사용자 확정으로 그대로 포함. GK는 대체 실측 없음. ④ **카마라 그리드는 pivot-centre 기준**(사용자 확정) — 우측 표본(n=7)으로는 dm_dlp/Roaming .873까지 오른다. 측정 기준은 obs#82를 따른다(정본 x=툴 SQUAD_SLOTS, 툴 함수 직접 호출, 회귀 게이트 통과).');
